function buildDecisions(page) {
  const root = pageRoot(page, {
    title: 'Decisions & glossary',
    intro: 'The main choices behind the platform, why they were made and what they cost, so that a new team member can tell which parts are deliberate and which are open to change.',
  });
  const c1 = docCard(root, { num: '9.1', kind: 'Architecture decision records', title: 'Why it is built this way' });
  table(c1, [['Decision', 300], ['Why', 520], ['Trade-off', 460], ['Status', 140]], [
    ['One Flutter codebase for web, Android, iOS, Windows and macOS', 'One small team, one UI that matches the Figma design everywhere.', 'USB works only in the web build for now.', 'Built'],
    ['USB from the browser: Web Serial + esptool-js', 'Nothing to install on school computers; the ESP32-S3’s own USB means no driver and no USB-serial chip.', 'Needs Chrome or Edge on a computer.', 'Built, waits for the board'],
    ['Compile on a server (arduino-cli in Docker)', 'The ESP32 toolchain is several hundred MB and school internet is slow; one pinned toolchain gives every student the same build.', 'Real uploads need internet and hosting; the free host sleeps (about a minute to wake).', 'Built'],
    ['A preview check and a simulated board in the app', 'Students can write, check and run code with no board and no internet, and see errors worded like the Arduino compiler’s.', 'Not a full C++ compiler: some sketches need the real board (marked realOnly).', 'Built'],
    ['Arduino C++, not MicroPython (for now)', 'Matches Arduino IDE 2, which works offline with the same library, and the C++ the blocks show.', 'Each upload compiles (seconds to tens of seconds). MicroPython stays an option.', 'Chosen'],
    ['Projects stay on the device; no accounts', 'No student data to protect or lose; nothing to sign up for.', 'No sync or sharing between devices yet.', 'Built'],
    ['One pin map, generated into the app and checked in CI', 'The library, the examples and the blocks can never disagree about a pin.', 'Changing a pin means editing the header and re-running the generator.', 'Built'],
    ['Pin every version', 'Flutter 3.47.7, arduino-cli 1.5.1, esp32 core 3.3.12, libraries and actions by commit, so builds repeat exactly.', 'Updates are deliberate work.', 'Built'],
    ['ESP32-S3 + XRP-compatible motors + 1S Li-ion with on-board charging and protection', 'Native USB, XRP’s proven motor and IMU choices, a battery that charges from USB-C and is protected from wrong packs.', 'The board needs 4 layers and small parts, so the first boards are made in China.', 'Board in manufacture'],
    ['A small, careful compile server', 'Compiles only, never runs code; unprivileged user; throwaway folders; size, time, queue and rate limits; a CORS allow-list.', 'One build at a time on the free plan.', 'Built'],
  ], { name: 'Decisions table' });
  const c2 = docCard(root, { num: '9.2', kind: 'Glossary', title: 'Words used in this file' });
  table(c2, [['Term', 260], ['Meaning', 900]], [
    ['AppState', 'The one object in the IDE that holds all state and runs Verify, Upload and the USB link. Screens listen to it.'],
    ['BoardIO', 'The interface the interpreter talks to when it runs a sketch; SimBoard implements it.'],
    ['CDC', 'USB Communications Device Class: how the board’s Serial appears as a serial port on the computer.'],
    ['Compile server', 'The Docker service that runs arduino-cli and returns the program in four parts.'],
    ['esptool-js', 'Espressif’s flasher in JavaScript; writes programs to ESP32 chips over Web Serial.'],
    ['FQBN', 'Fully qualified board name for arduino-cli; for the V2: esp32:esp32:esp32s3 with USB, flash, partition and PSRAM options.'],
    ['Preview board', 'The simulated RoboCore inside the IDE (SimBoard), used when no real board is connected.'],
    ['Preview check', 'The IDE’s own check of a sketch (compileSketch), used when no compile server is set.'],
    ['PSRAM', 'Extra RAM next to the ESP32-S3; the N8R2 module has 2 MB of quad PSRAM.'],
    ['RC_PIN_…', 'The pin names in RoboCoreV2Pins.h, e.g. RC_PIN_BUZZER = 47.'],
    ['1S, 1S3P', 'One cell in series; 1S3P = three cells in parallel, still 3.0–4.2 V.'],
    ['VMOT', 'The 5.5 V rail for the motors and servos, off when the switch is OFF.'],
    ['Web Serial', 'The browser API (Chrome, Edge) that lets a web page open a serial port after the user picks it.'],
    ['XRP', 'SparkFun’s Experiential Robotics Platform; RoboCore V2 uses the same motors and IMU and fixes some of its limits.'],
  ], { name: 'Glossary table' });
  return root;
}
// ============================================================================
// Orchestration: guard → pages → tokens → assets → one page at a time
// → (optional) PNG export to a local review server
// ============================================================================

async function yieldUI() { await new Promise(r => setTimeout(r, 0)); }

async function preparePages() {
  const managed = Object.values(PAGE_NAMES);
  for (const p of figma.root.children) await p.loadAsync();
  const foreign = figma.root.children.filter(p => managed.indexOf(p.name) < 0 && p.children.length > 0);
  if (foreign.length) throw new Error('This file already has other content (page "' + foreign[0].name + '"). Run the builder in a new, empty design file.');
  const built = figma.root.children.filter(p => managed.indexOf(p.name) >= 0 && p.children.length > 0);
  if (built.length && figma.command !== 'rebuild') throw new Error('This file already has the generated pages. Use Plugins → Development → RoboCore Architecture Builder → Rebuild to regenerate them (manual edits on those pages are replaced; version history keeps the old version).');
  const pages = {};
  const empties = figma.root.children.filter(p => managed.indexOf(p.name) < 0 && p.children.length === 0);
  for (const [key, name] of Object.entries(PAGE_NAMES)) {
    let p = figma.root.children.find(x => x.name === name);
    if (!p && empties.length) { p = empties.shift(); p.name = name; }
    if (!p) { p = figma.createPage(); p.name = name; }
    pages[key] = p;
  }
  Object.values(PAGE_NAMES).forEach((name, i) => { const p = figma.root.children.find(x => x.name === name); if (p) figma.root.insertChild(i, p); });
  for (const p of figma.root.children.slice()) if (managed.indexOf(p.name) < 0 && p.children.length === 0 && figma.root.children.length > managed.length) p.remove();
  for (const p of Object.values(pages)) for (const c of p.children.slice()) c.remove();
  return pages;
}

function buildAssets(page) {
  const root = box({ name: 'Assets', dir: 'V', gap: 32, pad: 64, fill: 'color/bg/app', parent: page });
  root.x = 0; root.y = 0;
  docHeader(root, 'Components used by the diagrams', 'Icons & logo', 'Lucide icons (2 px stroke on a 24 px grid) and the RoboCore wordmark, as components. The diagram pages use instances of these.');
  buildIcons(root);
  buildLogos(root);
  return root;
}

function waitForUI(type, ms) {
  return new Promise((resolve) => {
    const t = setTimeout(() => { figma.ui.off('message', h); resolve(null); }, ms);
    const h = (msg) => { if (msg && msg.type === type) { clearTimeout(t); figma.ui.off('message', h); resolve(msg); } };
    figma.ui.on('message', h);
  });
}
let UI_OPEN = false;
async function openReview() {
  if (!UI_OPEN) { figma.showUI(__html__, { visible: false, width: 240, height: 80 }); UI_OPEN = true; }
  for (let i = 0; i < 4; i++) {
    figma.ui.postMessage({ type: 'ping' });
    const pong = await waitForUI('pong', 3000);
    if (pong && pong.ok) return true;
  }
  return false;
}
async function exportForReview(items) {
  let n = 0;
  for (const [name, node, scale] of items) {
    if (!node || node.removed) continue;
    try {
      const bytes = await node.exportAsync({ format: 'PNG', constraint: { type: 'SCALE', value: scale } });
      figma.ui.postMessage({ type: 'png', name, bytes });
      await waitForUI('ack', 20000);
      n++;
    } catch (e) { warn('export ' + name + ': ' + e.message); }
  }
  REPORT.exported = (REPORT.exported || 0) + n;
}
async function sendReport() {
  try {
    figma.ui.postMessage({ type: 'report', report: REPORT });
    await waitForUI('ack', 8000);
  } catch (e) { /* UI not open */ }
}

const BUILDERS = [
  ['cover', buildCover], ['context', buildContext], ['containers', buildContainers], ['ide', buildIde], ['flows', buildFlows],
  ['states', buildStates], ['hardware', buildHardware], ['delivery', buildDelivery], ['cog', buildCog], ['decisions', buildDecisions],
];

async function main() {
  const T = Date.now();
  const mark = (k) => { REPORT.timings[k] = Date.now() - T; };
  const pages = await preparePages();
  await setupFonts();
  await setupTokens();
  mark('tokens');
  await figma.setCurrentPageAsync(pages.assets);
  buildAssets(pages.assets);
  await applyLinks();
  mark('assets');
  const roots = {};
  for (const [key, fn] of BUILDERS) {
    await figma.setCurrentPageAsync(pages[key]);
    try {
      roots[key] = fn(pages[key]);
    } catch (e) {
      REPORT.errors.push(key + ': ' + e.message + ' | ' + (e.stack || '').split('\n').slice(0, 4).join(' | '));
    }
    await applyLinks();
    mark(key);
    await yieldUI();
  }
  for (const p of Object.values(pages)) p.backgrounds = [{ type: 'SOLID', color: hexToRgb('#E9E2D2') }];

  const review = await openReview();
  REPORT.export = review ? 'on' : 'skipped (no local review server)';
  if (review) {
    for (const [key] of BUILDERS) {
      const r = roots[key];
      if (!r) continue;
      await figma.setCurrentPageAsync(pages[key]);
      const items = [[key + '__page.png', r, 0.25]];
      for (const c of r.children) {
        if (c.name.indexOf('Diagram') === 0) items.push([key + '_' + c.name.replace(/^Diagram /, '').replace(/[^\w.]+/g, '_').slice(0, 60) + '.png', c, 0.75]);
      }
      if (key === 'cover') for (const c of r.children) if (c.name !== 'Cover' && c.name.indexOf('Diagram') !== 0) items.push(['cover_' + c.name.replace(/[^\w]+/g, '_') + '.png', c, 0.6]);
      await exportForReview(items);
    }
  }
  REPORT.timings.total = Date.now() - T;
  await sendReport();
  await figma.setCurrentPageAsync(pages.cover);
  figma.viewport.scrollAndZoomIntoView(pages.cover.children);
}

main().then(() => {
  figma.closePlugin('RoboCore architecture built — ' + (REPORT.errors.length ? REPORT.errors.length + ' error(s), ' : '') + (REPORT.counts.diagrams || 0) + ' diagrams on ' + BUILDERS.length + ' pages');
}).catch(async (e) => {
  REPORT.errors.push('FATAL: ' + e.message + ' | ' + (e.stack || '').split('\n').slice(0, 6).join(' | '));
  try { if (await openReview()) await sendReport(); } catch (x) { /* ignore */ }
  figma.closePlugin('RoboCore architecture builder stopped: ' + e.message);
});
